"""Local reproducible review probes. No production data, network or repository edits.
Run from reviewed repository: python3 /tmp/.../probes.py [case].
rc=0 means the CURRENT defect was reproduced, not that production is correct.
"""
import contextlib, copy, hashlib, importlib.util, io, json, os, subprocess, sys, tempfile, threading, traceback
from pathlib import Path
from datetime import datetime, timezone
from unittest.mock import patch
