CASES = {}
def case(fn):
    CASES[fn.__name__] = fn
    return fn

def write(p, value):
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(value if isinstance(value, str) else json.dumps(value), encoding='utf-8')

def git(p, *args):
    return subprocess.check_output(['git','-C',str(p),'-c','user.name=Review','-c','user.email=review@example.invalid','-c','commit.gpgsign=false',*args],text=True,stderr=subprocess.PIPE).strip()

def init(p):
    p.mkdir(parents=True,exist_ok=True)
    git(p,'init','-q')
    write(p/'seed','seed\n')
    return commit(p)

def commit(p):
    git(p,'add','-A')
    git(p,'commit','-qm','fixture')
    return git(p,'rev-parse','HEAD')

def posts(p, rows, handle='alice'):
    write(p/'data/corpus'/handle/'posts.jsonl',''.join(json.dumps(r)+'\n' for r in rows))

def market(p, tickers=('AAA','BBB'), n=24):
    from datetime import date, timedelta
    days=[str(date(2026,1,2)+timedelta(days=i)) for i in range(n)]
    write(p/'market.csv','ticker,date,close\n'+''.join(f'{t},{d},{100+i}\n' for t in tickers for i,d in enumerate(days)))
    return p/'market.csv'

def exception(fn, typ):
    try: fn()
    except typ as e: return type(e).__name__+': '+str(e)
    raise AssertionError('expected '+typ.__name__)

@case
def qualification_wrong_sha(p):
    from qualification_runner import run_qualification
    init(p)
    write(p/'tests/test_sample.py','def test_sample():\n    assert False\n')
    red_sha=commit(p)
    red=run_qualification(red_sha,p)
    write(p/'tests/test_sample.py','def test_sample():\n    assert True\n')
    green_sha=commit(p)
    got=run_qualification(red_sha,p)
    assert not red.passed and got.passed and got.sha==red_sha and red_sha!=green_sha
    return 'same requested SHA: original checkout passed=False; different HEAD passed=True, labelled with original failing SHA'

