@case
def supervisor_tmp_collision(p):
    import supervisor_state as S
    barrier=threading.Barrier(2); real=os.replace; errors=[]
    def replace(a,b):
        barrier.wait(timeout=5)
        return real(a,b)
    def worker(i):
        try: S.atomic_write_json(p/'state.json',{'writer':i})
        except Exception as e: errors.append(type(e).__name__)
    with patch.object(S.os,'replace',replace):
        threads=[threading.Thread(target=worker,args=(i,)) for i in range(2)]
        for t in threads:t.start()
        for t in threads:t.join(timeout=7)
    assert errors==['FileNotFoundError']
    return 'two concurrent atomic_write_json calls: one FileNotFoundError due to shared state.json.tmp'

@case
def worktree_moving_base(p):
    from worktree_manager import WorktreeManager
    repo=p/'repo'; init(repo)
    wm=WorktreeManager(repo,p/'trees'); original=git(repo,'rev-parse','HEAD'); real=wm._worktree_add
    def advance(path,*args):
        write(repo/'new','advanced\n');commit(repo)
        return real(path,*args)
    with patch.object(wm,'_worktree_add',advance):
        info=wm.create_worktree('mission')
    actual=git(info.path,'rev-parse','HEAD')
    assert info.base_commit==original and actual!=original
    return 'base_commit pins initial SHA; created worktree HEAD is a later SHA after base_branch moved'

