@case
def operate_dirty_receipt(p):
    init(p);write(p/'artifact','v1');s1=commit(p);write(p/'artifact','v2');s2=commit(p)
    def rec(sha,body,date,corpus):
        return {'schema':OP.SCHEMA,'project':'TR_WEEKLY_DEEP_REFRESH_V1','trigger_source':'scheduler','observed_at':date,'observed_by':'supervisor','rc':0,'command':'refresh','refresh_sha':sha,'corpus_sha':corpus*64,'artifacts':[{'path':'artifact','sha256':hashlib.sha256(body.encode()).hexdigest()}]}
    a=rec(s1,'v1','2026-06-01T12:00:00Z','a');b=rec(s2,'v2','2026-06-02T12:00:00Z','b')
    write(p/'receipts/1.json',a);write(p/'receipts/2.json',b);commit(p)
    now=datetime(2026,6,15,tzinfo=timezone.utc)
    before=OP.verify(p/'receipts',p,now=now)[0]
    b['observed_at']='2026-06-08T12:00:00Z';write(p/'receipts/2.json',b)
    after=OP.verify(p/'receipts',p,now=now)[0]
    assert before==2 and after==0 and '2026-06-02' in git(p,'show','HEAD:receipts/2.json')
    return 'committed 1-day gap rc=2; change receipt date only in working tree to 7-day gap -> rc=0 and proof written'

