@case
def weekly_index_lost_update(p):
    real_read=WO._read_index
    # Deterministically interleave two complete stores at the index read boundary.
    # Both operations succeed; no simultaneous temp write is needed for this loss.
    first=WO.WeeklyRefreshObservation(WO.SCHEMA,WO.PROJECT,1,'scheduler','a'*64,'b'*64,'c'*64,'one',0,'supervisor')
    second=WO.WeeklyRefreshObservation(WO.SCHEMA,WO.PROJECT,2,'scheduler','d'*64,'e'*64,'f'*64,'two',0,'supervisor')
    fired=False
    def nested(d):
        nonlocal fired
        data=real_read(d)
        if not fired:
            fired=True
            WO.store_observation(second,d)
        return data
    with patch.object(WO,'_read_index',nested): WO.store_observation(first,p)
    valid=WO.list_valid_observations(p)
    assert len(list(p.glob('*.json')))==3 and len(valid)==1
    return '2 successful stores, 2 observation files, only 1 indexed/valid observation after interleaved read-modify-write'

