if __name__=='__main__':
    selected=sys.argv[1:];results=[]
    for name,fn in CASES.items():
        if selected and name not in selected:continue
        try:
            with tempfile.TemporaryDirectory(prefix='m2-review-') as d:detail=fn(Path(d))
            row={'case':name,'rc':0,'output':detail}
        except Exception:
            row={'case':name,'rc':1,'output':traceback.format_exc()}
        results.append(row);print('TEST '+name+' : rc='+str(row['rc'])+' | '+row['output'],flush=True)
    if os.environ.get('M2_PROBE_RESULTS'):Path(os.environ['M2_PROBE_RESULTS']).write_text(json.dumps(results,indent=2)+'\n')
    sys.exit(any(r['rc'] for r in results))
